static void run(final FastScanner scanner, final PrintWriter out) {
    int N = scanner.nextInt();
    for (int i = 0; i <= N; i++) {
        for (int j = 0; j <= N; j++) {
            for (int k = 0; k <= N; k++) {
                if (i + j + k <= N) {
                    out.println(i + " " + j + " " + k);
                }
            }
        }
    }
}
